package org.gielinor.profilesync;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.VarbitID;

final class AchievementDiarySnapshot
{
	static final int SCHEMA_VERSION = 2;
	static final String SOURCE_VERSION = "runelite-1.13.6-varbits";
	private static final String SOURCE = "RuneLite achievement diary completion, count, and reward varbits";
	private static final int TIERS_PER_REGION = 4;
	private static final List<String> TIER_NAMES = Arrays.asList("easy", "medium", "hard", "elite");

	private static final List<RegionDefinition> REGIONS = Arrays.asList(
		region("ardougne", "Ardougne",
			tier(VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_EASY_COUNT, VarbitID.ARDOUGNE_EASY_REWARD, 10),
			tier(VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, VarbitID.ARDOUGNE_MED_COUNT, VarbitID.ARDOUGNE_MEDIUM_REWARD, 12),
			tier(VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_HARD_COUNT, VarbitID.ARDOUGNE_HARD_REWARD, 12),
			tier(VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE, VarbitID.ARDOUGNE_ELITE_COUNT, VarbitID.ARDOUGNE_ELITE_REWARD, 8)),
		region("desert", "Desert",
			tier(VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_EASY_COUNT, VarbitID.DESERT_EASY_REWARD, 11),
			tier(VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, VarbitID.DESERT_MED_COUNT, VarbitID.DESERT_MEDIUM_REWARD, 12),
			tier(VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_HARD_COUNT, VarbitID.DESERT_HARD_REWARD, 10),
			tier(VarbitID.DESERT_DIARY_ELITE_COMPLETE, VarbitID.DESERT_ELITE_COUNT, VarbitID.DESERT_ELITE_REWARD, 6)),
		region("falador", "Falador",
			tier(VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_EASY_COUNT, VarbitID.FALADOR_EASY_REWARD, 11),
			tier(VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, VarbitID.FALADOR_MED_COUNT, VarbitID.FALADOR_MEDIUM_REWARD, 14),
			tier(VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_HARD_COUNT, VarbitID.FALADOR_HARD_REWARD, 11),
			tier(VarbitID.FALADOR_DIARY_ELITE_COMPLETE, VarbitID.FALADOR_ELITE_COUNT, VarbitID.FALADOR_ELITE_REWARD, 6)),
		region("fremennik", "Fremennik",
			tier(VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_EASY_COUNT, VarbitID.FREMENNIK_EASY_REWARD, 10),
			tier(VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, VarbitID.FREMENNIK_MED_COUNT, VarbitID.FREMENNIK_MEDIUM_REWARD, 9),
			tier(VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_HARD_COUNT, VarbitID.FREMENNIK_HARD_REWARD, 9),
			tier(VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE, VarbitID.FREMENNIK_ELITE_COUNT, VarbitID.FREMENNIK_ELITE_REWARD, 6)),
		region("kandarin", "Kandarin",
			tier(VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_EASY_COUNT, VarbitID.KANDARIN_EASY_REWARD, 11),
			tier(VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, VarbitID.KANDARIN_MED_COUNT, VarbitID.KANDARIN_MEDIUM_REWARD, 14),
			tier(VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_HARD_COUNT, VarbitID.KANDARIN_HARD_REWARD, 11),
			tier(VarbitID.KANDARIN_DIARY_ELITE_COMPLETE, VarbitID.KANDARIN_ELITE_COUNT, VarbitID.KANDARIN_ELITE_REWARD, 7)),
		region("karamja", "Karamja",
			tier(VarbitID.ATJUN_EASY_DONE, VarbitID.KARAMJA_EASY_COUNT, VarbitID.ATJUN_EASY_REWARD, 10),
			tier(VarbitID.ATJUN_MED_DONE, VarbitID.KARAMJA_MED_COUNT, VarbitID.ATJUN_MED_REWARD, 19),
			tier(VarbitID.ATJUN_HARD_DONE, VarbitID.KARAMJA_HARD_COUNT, VarbitID.ATJUN_HARD_REWARD, 10),
			tier(VarbitID.KARAMJA_DIARY_ELITE_COMPLETE, VarbitID.KARAMJA_ELITE_COUNT, VarbitID.KARAMJA_ELITE_REWARD, 5)),
		region("kourend_kebos", "Kourend & Kebos",
			tier(VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_EASY_COUNT, VarbitID.KOUREND_EASY_REWARD, 12),
			tier(VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, VarbitID.KOUREND_MED_COUNT, VarbitID.KOUREND_MEDIUM_REWARD, 13),
			tier(VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_HARD_COUNT, VarbitID.KOUREND_HARD_REWARD, 10),
			tier(VarbitID.KOUREND_DIARY_ELITE_COMPLETE, VarbitID.KOUREND_ELITE_COUNT, VarbitID.KOUREND_ELITE_REWARD, 8)),
		region("lumbridge_draynor", "Lumbridge & Draynor",
			tier(VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_EASY_COUNT, VarbitID.LUMBRIDGE_EASY_REWARD, 12),
			tier(VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, VarbitID.LUMBRIDGE_MED_COUNT, VarbitID.LUMBRIDGE_MEDIUM_REWARD, 12),
			tier(VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_HARD_COUNT, VarbitID.LUMBRIDGE_HARD_REWARD, 11),
			tier(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE, VarbitID.LUMBRIDGE_ELITE_COUNT, VarbitID.LUMBRIDGE_ELITE_REWARD, 6)),
		region("morytania", "Morytania",
			tier(VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_EASY_COUNT, VarbitID.MORYTANIA_EASY_REWARD, 11),
			tier(VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, VarbitID.MORYTANIA_MED_COUNT, VarbitID.MORYTANIA_MEDIUM_REWARD, 11),
			tier(VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_HARD_COUNT, VarbitID.MORYTANIA_HARD_REWARD, 10),
			tier(VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE, VarbitID.MORYTANIA_ELITE_COUNT, VarbitID.MORYTANIA_ELITE_REWARD, 6)),
		region("varrock", "Varrock",
			tier(VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_EASY_COUNT, VarbitID.VARROCK_EASY_REWARD, 14),
			tier(VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, VarbitID.VARROCK_MED_COUNT, VarbitID.VARROCK_MEDIUM_REWARD, 13),
			tier(VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_HARD_COUNT, VarbitID.VARROCK_HARD_REWARD, 10),
			tier(VarbitID.VARROCK_DIARY_ELITE_COMPLETE, VarbitID.VARROCK_ELITE_COUNT, VarbitID.VARROCK_ELITE_REWARD, 5)),
		region("western_provinces", "Western Provinces",
			tier(VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_EASY_COUNT, VarbitID.WESTERN_EASY_REWARD, 11),
			tier(VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, VarbitID.WESTERN_MED_COUNT, VarbitID.WESTERN_MEDIUM_REWARD, 13),
			tier(VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_HARD_COUNT, VarbitID.WESTERN_HARD_REWARD, 13),
			tier(VarbitID.WESTERN_DIARY_ELITE_COMPLETE, VarbitID.WESTERN_ELITE_COUNT, VarbitID.WESTERN_ELITE_REWARD, 7)),
		region("wilderness", "Wilderness",
			tier(VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_EASY_COUNT, VarbitID.WILDERNESS_EASY_REWARD, 12),
			tier(VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, VarbitID.WILDERNESS_MED_COUNT, VarbitID.WILDERNESS_MEDIUM_REWARD, 11),
			tier(VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_HARD_COUNT, VarbitID.WILDERNESS_HARD_REWARD, 10),
			tier(VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE, VarbitID.WILDERNESS_ELITE_COUNT, VarbitID.WILDERNESS_ELITE_REWARD, 7))
	);

	private AchievementDiarySnapshot()
	{
	}

	static Map<String, Object> build(SignalReader reader)
	{
		Map<String, Object> result = new LinkedHashMap<>();
		Map<String, Object> regions = new LinkedHashMap<>();
		int completed = 0;
		int known = 0;
		for (RegionDefinition definition : REGIONS)
		{
			Map<String, Object> region = buildRegion(definition, reader);
			regions.put(definition.key, region);
			Integer regionCompleted = (Integer) region.get("completedTierCount");
			if (regionCompleted != null)
			{
				completed += regionCompleted;
				known += TIERS_PER_REGION;
			}
		}

		int total = REGIONS.size() * TIERS_PER_REGION;
		Integer completedTierCount = known == total ? completed : null;
		result.put("schemaVersion", SCHEMA_VERSION);
		result.put("source", SOURCE);
		result.put("sourceVersion", SOURCE_VERSION);
		result.put("completedTierCount", completedTierCount);
		result.put("totalTierCount", total);
		result.put("completionPercent", completedTierCount == null ? null : completedTierCount * 100.0 / total);
		result.put("allComplete", completedTierCount == null ? null : completedTierCount == total);
		result.put("regions", regions);
		return result;
	}

	private static Map<String, Object> buildRegion(RegionDefinition definition, SignalReader reader)
	{
		Map<String, Object> region = new LinkedHashMap<>();
		region.put("name", definition.name);
		int completed = 0;
		int known = 0;
		for (int index = 0; index < definition.tiers.length; index++)
		{
			Map<String, Object> tier = buildTier(definition.tiers[index], reader);
			region.put(TIER_NAMES.get(index), tier);
			Boolean tierComplete = (Boolean) tier.get("tierComplete");
			if (tierComplete != null)
			{
				known++;
				if (tierComplete)
				{
					completed++;
				}
			}
		}
		Integer completedTierCount = known == TIERS_PER_REGION ? completed : null;
		region.put("completedTierCount", completedTierCount);
		region.put("totalTierCount", TIERS_PER_REGION);
		region.put("allComplete", completedTierCount == null ? null : completedTierCount == TIERS_PER_REGION);
		return region;
	}

	private static Map<String, Object> buildTier(TierDefinition definition, SignalReader reader)
	{
		Integer completionValue = readNonNegative(reader, definition.completionVarbit);
		Integer rawCount = readNonNegative(reader, definition.countVarbit);
		Integer rewardValue = readNonNegative(reader, definition.rewardVarbit);
		Integer count = rawCount != null && rawCount <= definition.totalTaskCount ? rawCount : null;
		Boolean rewardClaimed = rewardValue == null ? null : rewardValue > 0;
		Boolean tierComplete;
		if ((completionValue != null && completionValue > 0)
			|| Boolean.TRUE.equals(rewardClaimed)
			|| (count != null && count == definition.totalTaskCount))
		{
			tierComplete = true;
		}
		else if (completionValue != null || count != null)
		{
			tierComplete = false;
		}
		else
		{
			tierComplete = null;
		}

		Integer completedTaskCount = Boolean.TRUE.equals(tierComplete)
			? Integer.valueOf(definition.totalTaskCount)
			: count;
		int availableSignals = (completionValue == null ? 0 : 1)
			+ (count == null ? 0 : 1)
			+ (rewardValue == null ? 0 : 1);
		String signalStatus = availableSignals == 3 ? "available" : availableSignals == 0 ? "unavailable" : "partial";

		Map<String, Object> tier = new LinkedHashMap<>();
		tier.put("complete", tierComplete);
		tier.put("value", rewardValue);
		tier.put("rewardClaimed", rewardClaimed);
		tier.put("tierComplete", tierComplete);
		tier.put("completedTaskCount", completedTaskCount);
		tier.put("totalTaskCount", definition.totalTaskCount);
		tier.put("signalStatus", signalStatus);
		return tier;
	}

	private static Integer readNonNegative(SignalReader reader, int varbitId)
	{
		try
		{
			Integer value = reader.read(varbitId);
			return value != null && value >= 0 ? value : null;
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	private static RegionDefinition region(String key, String name, TierDefinition... tiers)
	{
		return new RegionDefinition(key, name, tiers);
	}

	private static TierDefinition tier(int completionVarbit, int countVarbit, int rewardVarbit, int totalTaskCount)
	{
		return new TierDefinition(completionVarbit, countVarbit, rewardVarbit, totalTaskCount);
	}

	interface SignalReader
	{
		Integer read(int varbitId);
	}

	private static final class RegionDefinition
	{
		private final String key;
		private final String name;
		private final TierDefinition[] tiers;

		private RegionDefinition(String key, String name, TierDefinition[] tiers)
		{
			this.key = key;
			this.name = name;
			this.tiers = tiers;
		}
	}

	private static final class TierDefinition
	{
		private final int completionVarbit;
		private final int countVarbit;
		private final int rewardVarbit;
		private final int totalTaskCount;

		private TierDefinition(int completionVarbit, int countVarbit, int rewardVarbit, int totalTaskCount)
		{
			this.completionVarbit = completionVarbit;
			this.countVarbit = countVarbit;
			this.rewardVarbit = rewardVarbit;
			this.totalTaskCount = totalTaskCount;
		}
	}
}

package org.gielinor.profilesync;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(GielinorProfileSyncPlugin.CONFIG_GROUP)
public interface GielinorProfileSyncConfig extends Config
{
	@Range(min = 10, max = 1000)
	@ConfigItem(
		keyName = "exportIntervalTicks",
		name = "Export interval",
		description = "Game ticks between local snapshots. 100 ticks is about one minute."
	)
	default int exportIntervalTicks()
	{
		return 100;
	}
}

package org.gielinor.profilesync;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.kit.KitType;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Gielinor Profile Sync",
	legacyDataDirectory = "gielinor-profile-sync",
	internalName = "gielinor-profile-sync",
	description = "Exports a privacy-minded local profile for personal dashboards and progression tools.",
	tags = {"profile", "export", "json", "progress", "avatar"}
)
public class GielinorProfileSyncPlugin extends Plugin
{
	static final String CONFIG_GROUP = "gielinor-profile-sync";
	private static final String PLUGIN_VERSION = "0.1.2";
	private static final int SCHEMA_VERSION = 1;
	private static final int LOGIN_SETTLE_TICKS = 5;

	@Inject
	private Client client;

	@Inject
	private Gson gson;

	@Inject
	private ItemManager itemManager;

	@Inject
	private GielinorProfileSyncConfig config;

	private ExecutorService fileExecutor;
	private ProfileExportStore exportStore;
	private volatile Map<String, Object> previousSnapshot = Collections.emptyMap();
	private int ticksLoggedIn;
	private int ticksSinceExport;
	private String lastRsn = "";
	private CachedContainer lastGoodBank;
	private CachedContainer lastGoodInventory;
	private CachedContainer lastGoodEquipment;

	@Provides
	GielinorProfileSyncConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GielinorProfileSyncConfig.class);
	}

	@Override
	protected void startUp()
	{
		exportStore = null;
		fileExecutor = Executors.newSingleThreadExecutor(runnable ->
		{
			Thread thread = new Thread(runnable, CONFIG_GROUP + "-writer");
			thread.setDaemon(true);
			return thread;
		});
		fileExecutor.execute(() ->
		{
			try
			{
				previousSnapshot = getExportStore().readLatest();
			}
			catch (IOException e)
			{
				log.warn("Could not initialize the local profile directory.", e);
			}
		});
		log.info("Gielinor Profile Sync started.");
	}

	@Override
	protected void shutDown()
	{
		if (fileExecutor != null)
		{
			fileExecutor.shutdownNow();
			fileExecutor = null;
		}
		resetSession();
		log.info("Gielinor Profile Sync stopped.");
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();
		if (containerId == InventoryID.BANK || containerId == InventoryID.INV || containerId == InventoryID.WORN)
		{
			ticksSinceExport = Math.max(10, config.exportIntervalTicks());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		if (client.getGameState() != GameState.LOGGED_IN || player == null)
		{
			ticksLoggedIn = 0;
			ticksSinceExport = 0;
			return;
		}

		String rsn = player.getName();
		if (rsn == null || rsn.trim().isEmpty())
		{
			return;
		}

		if (!rsn.equals(lastRsn))
		{
			resetAccount(rsn);
		}

		ticksLoggedIn++;
		ticksSinceExport++;
		if (ticksLoggedIn < LOGIN_SETTLE_TICKS)
		{
			return;
		}

		int interval = Math.max(10, config.exportIntervalTicks());
		if (ticksSinceExport < interval)
		{
			return;
		}

		ticksSinceExport = 0;
		exportSnapshot(player, rsn);
	}

	private void exportSnapshot(Player player, String rsn)
	{
		long now = System.currentTimeMillis();
		Map<String, Object> snapshot = new LinkedHashMap<>();
		snapshot.put("schemaVersion", SCHEMA_VERSION);
		snapshot.put("version", PLUGIN_VERSION);
		snapshot.put("timestamp", now);
		snapshot.put("timestampIso", Instant.ofEpochMilli(now).toString());
		snapshot.put("source", buildSource());
		snapshot.put("capabilities", Arrays.asList("skills", "quests", "achievementDiaries", "achievementDiaryTaskProgress", "slayerTask", "containers", "grandExchange", "appearance", "playerModel"));
		snapshot.put("rsn", rsn);
		snapshot.put("combatLevel", player.getCombatLevel());
		snapshot.put("totalLevel", calculateTotalLevel());
		snapshot.put("totalXp", calculateTotalXp());
		snapshot.put("skills", buildSkills());
		snapshot.put("appearance", buildAppearance(player));

		CachedContainer inventory = chooseContainer("inventory", buildContainer(InventoryID.INV), lastGoodInventory, now, rsn);
		CachedContainer equipment = chooseContainer("equipment", buildContainer(InventoryID.WORN), lastGoodEquipment, now, rsn);
		CachedContainer bank = chooseContainer("bank", buildContainer(InventoryID.BANK), lastGoodBank, now, rsn);
		lastGoodInventory = inventory;
		lastGoodEquipment = equipment;
		lastGoodBank = bank;

		putContainer(snapshot, "inventory", inventory);
		putContainer(snapshot, "equipment", equipment);
		putContainer(snapshot, "bank", bank);

		long inventoryValue = inventory.loaded ? getLong(inventory.data.get("value")) : 0;
		long equipmentValue = equipment.loaded ? getLong(equipment.data.get("value")) : 0;
		long bankValue = bank.loaded ? getLong(bank.data.get("value")) : 0;
		snapshot.put("inventoryValue", inventoryValue);
		snapshot.put("equipmentValue", equipmentValue);
		snapshot.put("bankValue", bankValue);
		snapshot.put("bankItemCount", bank.loaded ? getInt(bank.data.get("itemCount")) : 0);
		snapshot.put("carriedValue", inventoryValue + equipmentValue);
		snapshot.put("knownAccountValue", inventoryValue + equipmentValue + bankValue);

		Map<String, Object> grandExchange = buildGrandExchangeOffers();
		snapshot.put("grandExchange", grandExchange);
		snapshot.put("grandExchangeAccountValueEstimate", getLong(grandExchange.get("accountValueEstimate")));
		snapshot.put("quests", buildQuests());
		snapshot.put("achievementDiaries", AchievementDiarySnapshot.build(client::getVarbitValue));
		snapshot.put("slayer", SlayerTaskSnapshot.build(client, now));

		ExecutorService executor = fileExecutor;
		if (executor != null)
		{
			executor.execute(() -> writeSnapshot(rsn, snapshot));
		}
	}

	private Map<String, Object> buildSource()
	{
		Map<String, Object> source = new LinkedHashMap<>();
		source.put("name", "Gielinor Profile Sync");
		source.put("version", PLUGIN_VERSION);
		source.put("transport", "local-file");
		source.put("networkRequests", false);
		return source;
	}

	private ProfileExportStore getExportStore() throws IOException
	{
		if (exportStore == null)
		{
			exportStore = new ProfileExportStore(gson, getPluginDirectory());
		}
		return exportStore;
	}

	private void writeSnapshot(String rsn, Map<String, Object> snapshot)
	{
		try
		{
			getExportStore().write(rsn, snapshot);
			previousSnapshot = snapshot;
			log.debug("Wrote local profile snapshot for {}.", rsn);
		}
		catch (IOException e)
		{
			log.warn("Could not write the local profile snapshot.", e);
		}
	}

	private Map<String, Object> buildSkills()
	{
		Map<String, Object> skills = new LinkedHashMap<>();
		for (Skill skill : Skill.values())
		{
			Map<String, Object> data = new LinkedHashMap<>();
			data.put("level", client.getRealSkillLevel(skill));
			data.put("boostedLevel", client.getBoostedSkillLevel(skill));
			data.put("xp", client.getSkillExperience(skill));
			skills.put(skill.getName(), data);
		}
		return skills;
	}

	private int calculateTotalLevel()
	{
		int total = 0;
		for (Skill skill : Skill.values())
		{
			total += client.getRealSkillLevel(skill);
		}
		return total;
	}

	private long calculateTotalXp()
	{
		long total = 0;
		for (Skill skill : Skill.values())
		{
			total += client.getSkillExperience(skill);
		}
		return total;
	}

	private Map<String, Object> buildAppearance(Player player)
	{
		Map<String, Object> appearance = new LinkedHashMap<>();
		PlayerComposition composition = player.getPlayerComposition();
		appearance.put("loaded", composition != null);
		if (composition == null)
		{
			return appearance;
		}

		appearance.put("gender", composition.getGender());
		appearance.put("colors", toIntegerList(composition.getColors()));
		appearance.put("equipmentIds", toIntegerList(composition.getEquipmentIds()));
		appearance.put("transformedNpcId", composition.getTransformedNpcId());
		Map<String, Object> model = PlayerModelSnapshot.from(player.getModel());
		if (model != null)
		{
			appearance.put("model", model);
		}

		Map<String, Object> slots = new LinkedHashMap<>();
		for (KitType kitType : KitType.values())
		{
			int rawId = composition.getEquipmentId(kitType);
			Map<String, Object> slot = new LinkedHashMap<>();
			slot.put("rawId", rawId);
			if (rawId >= PlayerComposition.ITEM_OFFSET)
			{
				slot.put("kind", "item");
				slot.put("id", rawId - PlayerComposition.ITEM_OFFSET);
			}
			else if (rawId >= PlayerComposition.KIT_OFFSET)
			{
				slot.put("kind", "kit");
				slot.put("id", rawId - PlayerComposition.KIT_OFFSET);
			}
			else
			{
				slot.put("kind", "empty");
				slot.put("id", -1);
			}
			slots.put(kitType.name().toLowerCase(), slot);
		}
		appearance.put("slots", slots);
		return appearance;
	}

	private List<Integer> toIntegerList(int[] values)
	{
		List<Integer> output = new ArrayList<>(values.length);
		for (int value : values)
		{
			output.add(value);
		}
		return output;
	}

	private Map<String, Object> buildContainer(int inventoryId)
	{
		Map<String, Object> result = new LinkedHashMap<>();
		ItemContainer container = client.getItemContainer(inventoryId);
		boolean loaded = container != null;
		result.put("loaded", loaded);

		long totalValue = 0;
		int itemCount = 0;
		Map<String, Object> items = new LinkedHashMap<>();
		if (container != null)
		{
			Item[] containerItems = container.getItems();
			for (int slotIndex = 0; slotIndex < containerItems.length; slotIndex++)
			{
				Item item = containerItems[slotIndex];
				if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
				{
					continue;
				}

				int id = item.getId();
				int quantity = item.getQuantity();
				long price = itemManager.getItemPrice(id);
				long value = (long) price * quantity;
				Map<String, Object> itemData = new LinkedHashMap<>();
				itemData.put("slot", slotIndex);
				itemData.put("id", id);
				itemData.put("name", itemManager.getItemComposition(id).getName());
				itemData.put("quantity", quantity);
				itemData.put("price", price);
				itemData.put("value", value);
				items.put(String.valueOf(slotIndex), itemData);
				totalValue += value;
				itemCount++;
			}
		}

		result.put("value", totalValue);
		result.put("itemCount", itemCount);
		result.put("items", items);
		return result;
	}

	private CachedContainer chooseContainer(String key, Map<String, Object> current, CachedContainer memory, long now, String rsn)
	{
		if (Boolean.TRUE.equals(current.get("loaded")))
		{
			return new CachedContainer(current, true, false, now);
		}
		if (memory != null && memory.loaded)
		{
			return new CachedContainer(memory.data, true, true, memory.lastSeenTimestamp);
		}

		Map<String, Object> previous = previousSnapshot;
		if (rsn.equals(previous.get("rsn")) && previous.get(key) instanceof Map)
		{
			@SuppressWarnings("unchecked")
			Map<String, Object> previousContainer = (Map<String, Object>) previous.get(key);
			if (Boolean.TRUE.equals(previousContainer.get("loaded")))
			{
				long lastSeen = getLong(previous.get(key + "LastSeenTimestamp"));
				if (lastSeen <= 0)
				{
					lastSeen = getLong(previous.get("timestamp"));
				}
				return new CachedContainer(previousContainer, true, true, lastSeen);
			}
		}

		return new CachedContainer(current, false, false, 0);
	}

	private void putContainer(Map<String, Object> snapshot, String key, CachedContainer container)
	{
		snapshot.put(key, container.data);
		snapshot.put(key + "Loaded", container.loaded);
		snapshot.put(key + "FromCache", container.fromCache);
		snapshot.put(key + "LastSeenTimestamp", container.lastSeenTimestamp);
	}

	private Map<String, Object> buildGrandExchangeOffers()
	{
		Map<String, Object> result = new LinkedHashMap<>();
		Map<String, Object> offersOut = new LinkedHashMap<>();
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		result.put("loaded", offers != null);
		int activeCount = 0;
		long listedValueEstimate = 0;
		long accountValueEstimate = 0;

		if (offers != null)
		{
			for (int slotIndex = 0; slotIndex < offers.length; slotIndex++)
			{
				GrandExchangeOffer offer = offers[slotIndex];
				if (offer == null || offer.getState() == null || "EMPTY".equals(offer.getState().name()))
				{
					continue;
				}

				int itemId = offer.getItemId();
				long marketPrice = itemId > 0 ? itemManager.getItemPrice(itemId) : 0;
				int totalQuantity = offer.getTotalQuantity();
				int completedQuantity = offer.getQuantitySold();
				int remainingQuantity = Math.max(0, totalQuantity - completedQuantity);
				String state = offer.getState().name();
				long offerListedValue = (long) offer.getPrice() * totalQuantity;
				long offerAccountValue = estimateGrandExchangeValue(state, marketPrice, offer, completedQuantity, remainingQuantity);

				Map<String, Object> offerOut = new LinkedHashMap<>();
				offerOut.put("slot", slotIndex);
				offerOut.put("state", state);
				offerOut.put("itemId", itemId);
				offerOut.put("itemName", itemId > 0 ? itemManager.getItemComposition(itemId).getName() : "");
				offerOut.put("listedPrice", offer.getPrice());
				offerOut.put("marketPrice", marketPrice);
				offerOut.put("totalQuantity", totalQuantity);
				offerOut.put("completedQuantity", completedQuantity);
				offerOut.put("remainingQuantity", remainingQuantity);
				offerOut.put("spent", offer.getSpent());
				offerOut.put("listedValueEstimate", offerListedValue);
				offerOut.put("accountValueEstimate", offerAccountValue);
				offersOut.put(String.valueOf(slotIndex), offerOut);
				activeCount++;
				listedValueEstimate += offerListedValue;
				accountValueEstimate += offerAccountValue;
			}
		}

		result.put("activeCount", activeCount);
		result.put("listedValueEstimate", listedValueEstimate);
		result.put("accountValueEstimate", accountValueEstimate);
		result.put("offers", offersOut);
		return result;
	}

	private long estimateGrandExchangeValue(String state, long marketPrice, GrandExchangeOffer offer, int completed, int remaining)
	{
		if (state.contains("SELL"))
		{
			return (long) offer.getSpent() + (long) marketPrice * remaining;
		}
		if (state.contains("BUY"))
		{
			return (long) marketPrice * completed + (long) offer.getPrice() * remaining;
		}
		return (long) marketPrice * offer.getTotalQuantity();
	}

	private Map<String, Object> buildQuests()
	{
		Map<String, Object> result = new LinkedHashMap<>();
		Map<String, Object> entries = new LinkedHashMap<>();
		int notStarted = 0;
		int inProgress = 0;
		int finished = 0;
		int unknown = 0;

		for (Quest quest : Quest.values())
		{
			QuestState state;
			try
			{
				state = quest.getState(client);
			}
			catch (RuntimeException e)
			{
				state = null;
			}

			String stateName = state != null ? state.name() : "UNKNOWN";
			if (state == QuestState.NOT_STARTED)
			{
				notStarted++;
			}
			else if (state == QuestState.IN_PROGRESS)
			{
				inProgress++;
			}
			else if (state == QuestState.FINISHED)
			{
				finished++;
			}
			else
			{
				unknown++;
			}

			Map<String, Object> data = new LinkedHashMap<>();
			data.put("name", quest.getName());
			data.put("state", stateName);
			entries.put(quest.name(), data);
		}

		result.put("notStarted", notStarted);
		result.put("inProgress", inProgress);
		result.put("finished", finished);
		result.put("unknown", unknown);
		result.put("total", entries.size());
		result.put("entries", entries);
		return result;
	}

	private long getLong(Object value)
	{
		return value instanceof Number ? ((Number) value).longValue() : 0L;
	}

	private int getInt(Object value)
	{
		return value instanceof Number ? ((Number) value).intValue() : 0;
	}

	private void resetSession()
	{
		ticksLoggedIn = 0;
		ticksSinceExport = 0;
		lastRsn = "";
		lastGoodBank = null;
		lastGoodInventory = null;
		lastGoodEquipment = null;
	}

	private void resetAccount(String rsn)
	{
		lastRsn = rsn;
		lastGoodBank = null;
		lastGoodInventory = null;
		lastGoodEquipment = null;
		ticksSinceExport = Math.max(10, config.exportIntervalTicks());
	}

	private static final class CachedContainer
	{
		private final Map<String, Object> data;
		private final boolean loaded;
		private final boolean fromCache;
		private final long lastSeenTimestamp;

		private CachedContainer(Map<String, Object> data, boolean loaded, boolean fromCache, long lastSeenTimestamp)
		{
			this.data = data;
			this.loaded = loaded;
			this.fromCache = fromCache;
			this.lastSeenTimestamp = lastSeenTimestamp;
		}
	}
}

package org.gielinor.profilesync;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Model;

final class PlayerModelSnapshot
{
	private static final int MODEL_SCHEMA_VERSION = 1;

	private PlayerModelSnapshot()
	{
	}

	static Map<String, Object> from(Model model)
	{
		if (model == null)
		{
			return null;
		}

		return encode(
			model.getVerticesCount(),
			model.getVerticesX(),
			model.getVerticesY(),
			model.getVerticesZ(),
			model.getFaceCount(),
			model.getFaceIndices1(),
			model.getFaceIndices2(),
			model.getFaceIndices3(),
			model.getFaceColors1(),
			model.getFaceColors2(),
			model.getFaceColors3(),
			model.getFaceTransparencies(),
			model.getFaceTextures());
	}

	static Map<String, Object> encode(
		int vertexCount,
		float[] verticesX,
		float[] verticesY,
		float[] verticesZ,
		int faceCount,
		int[] faces1,
		int[] faces2,
		int[] faces3,
		int[] colors1,
		int[] colors2,
		int[] colors3,
		byte[] transparencies,
		short[] textures)
	{
		if (vertexCount <= 0 || faceCount <= 0 ||
			!hasLength(verticesX, vertexCount) ||
			!hasLength(verticesY, vertexCount) ||
			!hasLength(verticesZ, vertexCount) ||
			!hasLength(faces1, faceCount) ||
			!hasLength(faces2, faceCount) ||
			!hasLength(faces3, faceCount) ||
			!hasLength(colors1, faceCount) ||
			!hasLength(colors2, faceCount) ||
			!hasLength(colors3, faceCount))
		{
			return null;
		}

		Map<String, Object> output = new LinkedHashMap<>();
		output.put("schemaVersion", MODEL_SCHEMA_VERSION);
		output.put("vertexCount", vertexCount);
		output.put("faceCount", faceCount);
		output.put("verticesX", roundedCopy(verticesX, vertexCount));
		output.put("verticesY", roundedCopy(verticesY, vertexCount));
		output.put("verticesZ", roundedCopy(verticesZ, vertexCount));
		output.put("faces1", Arrays.copyOf(faces1, faceCount));
		output.put("faces2", Arrays.copyOf(faces2, faceCount));
		output.put("faces3", Arrays.copyOf(faces3, faceCount));
		output.put("colors1", Arrays.copyOf(colors1, faceCount));
		output.put("colors2", Arrays.copyOf(colors2, faceCount));
		output.put("colors3", Arrays.copyOf(colors3, faceCount));
		if (hasLength(transparencies, faceCount))
		{
			output.put("transparencies", unsignedCopy(transparencies, faceCount));
		}
		if (hasLength(textures, faceCount))
		{
			output.put("textures", integerCopy(textures, faceCount));
		}
		return output;
	}

	private static boolean hasLength(float[] values, int length)
	{
		return values != null && values.length >= length;
	}

	private static boolean hasLength(int[] values, int length)
	{
		return values != null && values.length >= length;
	}

	private static boolean hasLength(byte[] values, int length)
	{
		return values != null && values.length >= length;
	}

	private static boolean hasLength(short[] values, int length)
	{
		return values != null && values.length >= length;
	}

	private static int[] roundedCopy(float[] values, int length)
	{
		int[] output = new int[length];
		for (int index = 0; index < length; index++)
		{
			output[index] = Math.round(values[index]);
		}
		return output;
	}

	private static int[] unsignedCopy(byte[] values, int length)
	{
		int[] output = new int[length];
		for (int index = 0; index < length; index++)
		{
			output[index] = Byte.toUnsignedInt(values[index]);
		}
		return output;
	}

	private static int[] integerCopy(short[] values, int length)
	{
		int[] output = new int[length];
		for (int index = 0; index < length; index++)
		{
			output[index] = values[index];
		}
		return output;
	}
}

package org.gielinor.profilesync;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.Reader;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.Collections;
import java.util.Map;
import net.runelite.client.util.Filepath;

final class ProfileExportStore
{
	private final Gson gson;
	private final Filepath directory;

	ProfileExportStore(Gson gson, Filepath directory)
	{
		this.gson = gson.newBuilder().setPrettyPrinting().create();
		this.directory = directory;
	}

	@SuppressWarnings("unchecked")
	Map<String, Object> readLatest()
	{
		Filepath latest = directory.join("latest.json");
		if (!latest.isFile())
		{
			return Collections.emptyMap();
		}

		try (Reader reader = latest.openBufferedReader())
		{
			Map<String, Object> parsed = gson.fromJson(reader, Map.class);
			return parsed != null ? parsed : Collections.emptyMap();
		}
		catch (IOException | RuntimeException e)
		{
			return Collections.emptyMap();
		}
	}

	void write(String rsn, Map<String, Object> snapshot) throws IOException
	{
		directory.createDirectories();
		String json = gson.toJson(snapshot) + System.lineSeparator();
		writeAtomically(directory.join("latest.json"), json);
		writeAtomically(directory.join(safeFileName(rsn) + ".json"), json);
	}

	private void writeAtomically(Filepath destination, String json) throws IOException
	{
		Filepath temporary = directory.join(destination.getFileName() + ".tmp");
		temporary.write(json);
		try
		{
			temporary.moveTo(destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (AtomicMoveNotSupportedException e)
		{
			temporary.moveTo(destination, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	static String safeFileName(String rsn)
	{
		String safe = rsn == null ? "" : rsn.replaceAll("[^a-zA-Z0-9 _-]+", "_").trim();
		safe = safe.replaceAll("^[ _.]+|[ _.]+$", "");
		if (safe.isEmpty())
		{
			return "player";
		}
		if (safe.matches("(?i)CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9]"))
		{
			return "_" + safe;
		}
		return safe;
	}
}

package org.gielinor.profilesync;

import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/** Reads only the server-backed assignment state RuneLite uses for its Slayer counter. */
final class SlayerTaskSnapshot
{
	private static final int BOSS_TASK_ID = 98;
	private static final int KRYSTILIA_SLAYER_MASTER = 7;
	private static final int MAX_GAME_LABEL_LENGTH = 120;

	interface Source
	{
		int varp(int id);
		int varbit(int id);
		List<Integer> rowsByValue(int tableId, int columnId, int tupleIndex, Object value);
		Object[] field(int rowId, int columnId, int tupleIndex);
	}

	private SlayerTaskSnapshot()
	{
	}

	static Map<String, Object> build(Client client, long observedAt)
	{
		return build(new Source()
		{
			@Override
			public int varp(int id)
			{
				return client.getVarpValue(id);
			}

			@Override
			public int varbit(int id)
			{
				return client.getVarbitValue(id);
			}

			@Override
			public List<Integer> rowsByValue(int tableId, int columnId, int tupleIndex, Object value)
			{
				return client.getDBRowsByValue(tableId, columnId, tupleIndex, value);
			}

			@Override
			public Object[] field(int rowId, int columnId, int tupleIndex)
			{
				return client.getDBTableField(rowId, columnId, tupleIndex);
			}
		}, observedAt);
	}

	static Map<String, Object> build(Source source, long observedAt)
	{
		Map<String, Object> result = base(false, observedAt);
		try
		{
			int remaining = source.varp(VarPlayerID.SLAYER_COUNT);
			int original = source.varp(VarPlayerID.SLAYER_COUNT_ORIGINAL);
			int taskId = source.varp(VarPlayerID.SLAYER_TARGET);
			int areaId = source.varp(VarPlayerID.SLAYER_AREA);
			int masterId = source.varbit(VarbitID.SLAYER_MASTER);

			result = base(true, observedAt);
			result.put("status", remaining > 0 ? "live" : "none");
			result.put("points", nonNegative(source.varbit(VarbitID.SLAYER_POINTS)));
			result.put("streak", nonNegative(source.varbit(
				masterId == KRYSTILIA_SLAYER_MASTER
					? VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED
					: VarbitID.SLAYER_TASKS_COMPLETED)));

			if (remaining <= 0)
			{
				result.put("task", null);
				return result;
			}

			Map<String, Object> task = new LinkedHashMap<>();
			task.put("taskId", nonNegative(taskId));
			task.put("remaining", nonNegative(remaining));
			task.put("original", original > 0 ? original : null);
			task.put("assignedById", nonNegative(masterId));
			task.put("requiredLocationId", areaId > 0 ? areaId : null);

			Integer taskRow = resolveTaskRow(source, taskId);
			task.put("monster", taskRow == null
				? null
				: safeLabel(first(source.field(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0))));
			task.put("requiredLocation", resolveArea(source, areaId));
			task.put("identityKnown", task.get("monster") != null);
			result.put("task", task);
			return result;
		}
		catch (RuntimeException exception)
		{
			result.put("status", "unavailable");
			result.put("task", null);
			return result;
		}
	}

	private static Map<String, Object> base(boolean loaded, long observedAt)
	{
		Map<String, Object> result = new LinkedHashMap<>();
		result.put("schemaVersion", 1);
		result.put("source", "RuneLite server-backed Slayer assignment variables");
		result.put("sourceVersion", "runelite-1.13.6-task-vars");
		result.put("taskLoaded", loaded);
		result.put("taskFromCache", false);
		result.put("taskLastSeenTimestamp", loaded && observedAt > 0
			? Instant.ofEpochMilli(observedAt).toString()
			: null);
		result.put("status", loaded ? "none" : "unavailable");
		result.put("points", null);
		result.put("streak", null);
		result.put("task", null);
		return result;
	}

	private static Integer resolveTaskRow(Source source, int taskId)
	{
		if (taskId == BOSS_TASK_ID)
		{
			List<Integer> rows = source.rowsByValue(
				DBTableID.SlayerTaskSublist.ID,
				DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
				0,
				source.varbit(VarbitID.SLAYER_TARGET_BOSSID));
			if (rows == null || rows.isEmpty())
			{
				return null;
			}
			Object value = first(source.field(rows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0));
			return value instanceof Integer ? (Integer) value : null;
		}

		List<Integer> rows = source.rowsByValue(
			DBTableID.SlayerTask.ID,
			DBTableID.SlayerTask.COL_ID,
			0,
			taskId);
		return rows == null || rows.isEmpty() ? null : rows.get(0);
	}

	private static String resolveArea(Source source, int areaId)
	{
		if (areaId <= 0)
		{
			return null;
		}
		List<Integer> rows = source.rowsByValue(
			DBTableID.SlayerArea.ID,
			DBTableID.SlayerArea.COL_AREA_ID,
			0,
			areaId);
		if (rows == null || rows.isEmpty())
		{
			return null;
		}
		return safeLabel(first(source.field(rows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0)));
	}

	private static Object first(Object[] values)
	{
		return values == null || values.length == 0 ? null : values[0];
	}

	private static Integer nonNegative(int value)
	{
		return value >= 0 ? value : null;
	}

	private static String safeLabel(Object value)
	{
		if (!(value instanceof String))
		{
			return null;
		}
		String normalized = ((String) value)
			.replaceAll("<[^>]*>", "")
			.replaceAll("[\\p{Cntrl}<>]", "")
			.replaceAll("\\s+", " ")
			.trim();
		if (normalized.isEmpty())
		{
			return null;
		}
		return normalized.length() <= MAX_GAME_LABEL_LENGTH
			? normalized
			: normalized.substring(0, MAX_GAME_LABEL_LENGTH);
	}
}

package org.gielinor.profilesync;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class AchievementDiarySnapshotTest
{
	private static final List<String> REGION_KEYS = Arrays.asList(
		"ardougne", "desert", "falador", "fremennik", "kandarin", "karamja",
		"kourend_kebos", "lumbridge_draynor", "morytania", "varrock",
		"western_provinces", "wilderness"
	);

	@Test
	@SuppressWarnings("unchecked")
	public void exportsAllTwelveRegionsAndTheVerifiedCatalogueTotals()
	{
		Map<String, Object> snapshot = AchievementDiarySnapshot.build(varbitId -> 0);
		Map<String, Object> regions = (Map<String, Object>) snapshot.get("regions");

		assertEquals(2, snapshot.get("schemaVersion"));
		assertEquals("runelite-1.13.6-varbits", snapshot.get("sourceVersion"));
		assertEquals(REGION_KEYS, Arrays.asList(regions.keySet().toArray(new String[0])));
		assertEquals(48, snapshot.get("totalTierCount"));
		assertEquals(0, snapshot.get("completedTierCount"));
		assertEquals(false, snapshot.get("allComplete"));

		Map<String, int[]> expectedTotals = new LinkedHashMap<>();
		expectedTotals.put("ardougne", new int[]{10, 12, 12, 8});
		expectedTotals.put("desert", new int[]{11, 12, 10, 6});
		expectedTotals.put("falador", new int[]{11, 14, 11, 6});
		expectedTotals.put("fremennik", new int[]{10, 9, 9, 6});
		expectedTotals.put("kandarin", new int[]{11, 14, 11, 7});
		expectedTotals.put("karamja", new int[]{10, 19, 10, 5});
		expectedTotals.put("kourend_kebos", new int[]{12, 13, 10, 8});
		expectedTotals.put("lumbridge_draynor", new int[]{12, 12, 11, 6});
		expectedTotals.put("morytania", new int[]{11, 11, 10, 6});
		expectedTotals.put("varrock", new int[]{14, 13, 10, 5});
		expectedTotals.put("western_provinces", new int[]{11, 13, 13, 7});
		expectedTotals.put("wilderness", new int[]{12, 11, 10, 7});

		int taskTotal = 0;
		for (Map.Entry<String, Object> regionEntry : regions.entrySet())
		{
			Map<String, Object> region = (Map<String, Object>) regionEntry.getValue();
			int[] actualTotals = new int[4];
			int tierIndex = 0;
			for (String tierName : Arrays.asList("easy", "medium", "hard", "elite"))
			{
				Map<String, Object> tier = (Map<String, Object>) region.get(tierName);
				actualTotals[tierIndex++] = (Integer) tier.get("totalTaskCount");
				taskTotal += (Integer) tier.get("totalTaskCount");
				assertEquals("available", tier.get("signalStatus"));
			}
			assertArrayEquals(expectedTotals.get(regionEntry.getKey()), actualTotals);
		}
		assertEquals(492, taskTotal);
	}

	@Test
	public void exportsPartialTaskProgressWithoutClaimingCompletion()
	{
		Map<Integer, Integer> signals = signals(
			VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, 0,
			VarbitID.ARDOUGNE_EASY_COUNT, 3,
			VarbitID.ARDOUGNE_EASY_REWARD, 0);
		Map<String, Object> tier = tier(AchievementDiarySnapshot.build(id -> signals.getOrDefault(id, 0)), "ardougne", "easy");

		assertEquals(false, tier.get("tierComplete"));
		assertEquals(false, tier.get("rewardClaimed"));
		assertEquals(3, tier.get("completedTaskCount"));
		assertEquals(10, tier.get("totalTaskCount"));
	}

	@Test
	public void completionSignalWinsOverAStaleCountWithoutClaimingTheReward()
	{
		Map<Integer, Integer> signals = signals(
			VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, 1,
			VarbitID.ARDOUGNE_EASY_COUNT, 4,
			VarbitID.ARDOUGNE_EASY_REWARD, 0);
		Map<String, Object> tier = tier(AchievementDiarySnapshot.build(id -> signals.getOrDefault(id, 0)), "ardougne", "easy");

		assertEquals(true, tier.get("complete"));
		assertEquals(true, tier.get("tierComplete"));
		assertEquals(false, tier.get("rewardClaimed"));
		assertEquals(10, tier.get("completedTaskCount"));
	}

	@Test
	public void claimedRewardIsMonotonicPositiveCompletionEvidence()
	{
		Map<Integer, Integer> signals = signals(
			VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, 0,
			VarbitID.ARDOUGNE_EASY_COUNT, 2,
			VarbitID.ARDOUGNE_EASY_REWARD, 1);
		Map<String, Object> tier = tier(AchievementDiarySnapshot.build(id -> signals.getOrDefault(id, 0)), "ardougne", "easy");

		assertEquals(true, tier.get("tierComplete"));
		assertEquals(true, tier.get("rewardClaimed"));
		assertEquals(10, tier.get("completedTaskCount"));
		assertEquals(1, tier.get("value"));
